import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Wie trifft ein Tool eine exakte Dateigröße wie 80 KB, ohne zu raten? Die Antwort ist ein einfacher, eleganter Algorithmus namens binäre Suche.</p>\n<p>Die binäre Suche findet die beste Qualitätseinstellung für Ihr Bild in einer Handvoll Tests. Sie rät nie, begnügt sich nie mit einer runden Zahl und lässt nie Qualität ungenutzt.</p>\n<p>Dieser Artikel erklärt, wie die Suche funktioniert, warum sie manuelle Qualitätsschieberegler schlägt und wo ihre Grenzen liegen.</p>\n<h2 id=\"the-problem\">Das Problem: Qualität ist nicht vorhersagbar</h2>\n<p>Jedes Bild komprimiert sich anders. Ein Porträt mit 70 Prozent Qualität wiegt vielleicht 90 KB, während eine Landschaft mit derselben Einstellung 150 KB wiegt.</p>\n<p>Diese Unvorhersagbarkeit macht manuelle Qualitätsschieberegler für exakte Ziele nutzlos. 70 Prozent einzustellen und zu hoffen, ist keine Strategie.</p>\n<p>Man könnte Qualität für Qualität von Hand versuchen, aber jeder Test braucht Zeit. Die beste Einstellung manuell zu finden, könnte zwanzig Versuche brauchen.</p>\n<p>Das Tool löst das mit einer Suche. Es testet Qualitätsstufen systematisch, bis es die höchste findet, die noch zu Ihrem Ziel passt.</p>\n<p>Die Suche zu verstehen, hilft Ihnen, dem Ergebnis zu vertrauen. Es ist keine Magie, es ist Methode.</p>\n<h2 id=\"binary-search-basics\">Die Suche im Detail – einfach erklärt</h2>\n<p>Die binäre Suche arbeitet auf einem sortierten Bereich. Die Qualität läuft von niedrig nach hoch, und die Dateigröße steigt mit der Qualität – der Bereich ist also perfekt geordnet.</p>\n<p>Die Suche beginnt in der Mitte. Sie testet Qualität 50 und prüft, ob das Ergebnis unter das Ziel passt.</p>\n<p>Wenn das Ergebnis passt, muss die beste Qualität höher als 50 sein. Die Suche wechselt in die obere Hälfte und testet 75.</p>\n<p>Wenn das Ergebnis nicht passt, muss die beste Qualität niedriger als 50 sein. Die Suche wechselt in die untere Hälfte und testet 25.</p>\n<p>Jeder Test halbiert den übrigen Bereich. Nach etwa sieben Tests hat die Suche die beste Qualität auf einen einzigen Punkt eingegrenzt.</p>\n<h2 id=\"worked-example\">Ein durchgerechnetes Beispiel: 100 KB treffen</h2>\n<p>Stellen Sie sich ein Foto und ein Ziel von 100 KB vor. Die Suche beginnt mit dem Test von Qualität 50.</p>\n<p>Bei Qualität 50 wiegt die Datei 70 KB. Das passt, die beste Qualität liegt also irgendwo über 50. Die Suche testet 75.</p>\n<p>Bei Qualität 75 wiegt die Datei 120 KB. Das ist zu groß, die beste Qualität liegt also zwischen 50 und 75. Die Suche testet 62.</p>\n<p>Bei Qualität 62 wiegt die Datei 95 KB. Das passt, der Bereich verengt sich also auf zwischen 62 und 75. Die Suche testet 68.</p>\n<p>Bei Qualität 68 wiegt die Datei 104 KB. Wieder zu groß, der Bereich wird also 62 bis 68. Ein paar weitere Tests pendeln sich auf 65 ein, was bei 99 KB landet.</p>\n<p>Der ganze Vorgang dauert Sekunden. Ein Mensch, der dieselben Tests von Hand macht, bräuchte viele Minuten und weit mehr Geduld.</p>\n<h2 id=\"why-not-linear\">Warum die Suche schneller ist als Ausprobieren</h2>\n<p>Eine lineare Suche testet jede Qualitätsstufe der Reihe nach: 100, 99, 98 und so weiter. Sie funktioniert, aber sie ist langsam.</p>\n<p>Qualität 65 zu finden, indem man von 100 herunterzählt, braucht 35 Tests. Die binäre Suche findet sie in etwa sieben.</p>\n<p>Jeder Test bedeutet, das Bild neu zu kodieren, was echte Zeit kostet. Fünfunddreißig Kodierungen fühlen sich träge an; sieben fühlen sich sofort an.</p>\n<p>Die binäre Suche skaliert auch gut. Ob der Bereich 100 oder 1000 ist, die Anzahl der Tests wächst nur langsam.</p>\n<p>Diese Effizienz ist der Grund, warum sich das Tool selbst bei großen Bildern schnell anfühlt. Die Suche leistet die minimale Arbeit, die nötig ist, um die beste Antwort zu finden.</p>\n<h2 id=\"quality-first\">Warum die Qualität vor den Abmessungen kommt</h2>\n<p>Die Suche läuft zuerst in voller Auflösung. Das ist eine bewusste Entscheidung, denn Abmessungen sind den meisten Menschen wichtiger als ein kleiner Qualitätsunterschied.</p>\n<p>Ein Foto in voller Größe mit etwas niedrigerer Qualität sieht meist besser aus als ein kleineres Foto mit hoher Qualität. Das Auge bemerkt die Größe, bevor es die Komprimierung bemerkt.</p>\n<p>Erst wenn die Suche in voller Größe scheitert, beginnt die Skalierung. Das Tool testet dann kleinere Abmessungen und führt bei jedem Schritt eine frische Qualitätssuche durch.</p>\n<p>Diese Reihenfolge schützt Ihr Bild. Sie behält die Pixel, die Sie haben, und opfert nur die Qualität, die Sie nicht sehen können.</p>\n<p>Wenn ein Portal exakte Abmessungen verlangt, gilt die Reihenfolge trotzdem. Das Tool arbeitet härter allein an der Qualität und warnt Sie, wenn das Ziel nicht erreicht werden kann.</p>\n<h2 id=\"scaling-steps\">Wie die Abmessungsskalierungsschritte funktionieren</h2>\n<p>Wenn die Qualität allein das Ziel nicht erreichen kann, geht das Tool die Abmessungen schrittweise nach unten. Es testet Skalen wie 90 Prozent, 80 Prozent und darunter.</p>\n<p>Bei jeder Skala führt es eine frische binäre Suche nach der besten Qualität durch. Das heißt, jede Abmessung bekommt ihre eigene beste Qualitätseinstellung.</p>\n<p>Das Tool stoppt bei der ersten Skala, die passt. Ein 90-Prozent-Bild, das das Ziel trifft, wird behalten, statt unnötig auf 80 Prozent zu fallen.</p>\n<p>Die Schritte sind absichtlich klein. Eine schrittweise Verringerung bewahrt so viel Größe wie möglich und erreicht trotzdem das Ziel.</p>\n<p>Für die meisten Bilder ist eine Skalierung selten nötig. Sie taucht hauptsächlich bei sehr engen Zielen oder sehr großen Originalen auf.</p>\n<h2 id=\"accuracy-limits\">Genauigkeit und ihre Grenzen</h2>\n<p>Die Suche landet sehr nah am Ziel, meist innerhalb weniger Kilobyte. Sie zielt knapp unter die Grenze, um einen Sicherheitsspielraum zu lassen.</p>\n<p>Dieser Spielraum schützt vor Rundung. Eine Datei, die auf Ihrem Gerät als 100 KB angezeigt wird, kann in exakten Byte 100,4 KB groß sein, und der Spielraum deckt die Lücke ab.</p>\n<p>Manche Bilder besiegen die Suche. Ein hochdetailliertes Foto bei einem winzigen Ziel braucht vielleicht eine so drastische Skalierung, dass das Ergebnis unbrauchbar ist.</p>\n<p>In diesen Fällen meldet das Tool eine ehrliche Zielverfehlung. Es sagt Ihnen lieber, dass das Ziel nicht erreicht werden kann, als Ihnen ein ruiniertes Bild zu übergeben.</p>\n<p>Die Genauigkeit hängt auch vom Format ab. JPG und WebP geben der Suche feine Kontrolle, während PNG fast keine bietet – weshalb PNG-Ziele oft verfehlt werden.</p>\n<h2 id=\"vs-manual\">Qualitätssuche statt Schieberegler von Hand</h2>\n<p>Manuelle Schieberegler bitten Sie, eine Qualitätszahl zu wählen und zu hoffen. Die meisten Menschen wählen eine runde Zahl wie 70 oder 80, die selten die beste Wahl ist.</p>\n<p>Die beste Qualität für Ihr Bild könnte 63 oder 71 sein. Ein Mensch würde diese Zahl nie raten, aber die Suche findet sie in Sekunden.</p>\n<p>Manuelle Schieberegler verschwenden auch Zeit. Jeder Test bedeutet, den Schieberegler zu ändern, zu warten und die Größe zu prüfen – wiederholt, bis man Glück hat.</p>\n<p>Die Suche entfernt das Raten vollständig. Sie nennen das Ziel, und das Tool findet die beste Qualität, die dazu passt.</p>\n<p>Das ist der eigentliche Nutzen des Zielkompressors. Er verwandelt eine lästige Pflicht mit Versuch und Irrtum in einen einzigen selbstbewussten Klick.</p>\n<h2 id=\"batch-search\">Die Suche im Stapelmodus</h2>\n<p>Im Stapelmodus läuft die Suche für jedes Bild separat. Jede Datei bekommt ihre eigene beste Qualitätseinstellung, auch wenn sie ein Ziel teilen.</p>\n<p>Ein einfaches Porträt pendelt sich vielleicht bei Qualität 82 ein, während eine detailreiche Landschaft bei 61 landet. Beide treffen dasselbe Ziel mit ihren eigenen besten Einstellungen.</p>\n<p>Die Zusammenfassung verfolgt jede Datei einzeln. Sie zeigt, welche Dateien das Ziel getroffen und welche es verfehlt haben, damit Sie die Fehlschläge einzeln beheben können.</p>\n<p>Die Stapelsuche dauert länger als eine einzelne Suche, aber weit weniger Zeit, als jede Datei von Hand zu komprimieren. Das Tool übernimmt die sich wiederholende Arbeit für Sie.</p>\n<p>Sehen Sie sich zuerst die schwierigsten Dateien im Stapel in der Vorschau an. Sie haben am ehesten das Ziel verfehlt oder sichtbare Qualität verloren.</p>\n<h2 id=\"when-search-fails\">Wenn die Suche nicht helfen kann</h2>\n<p>Die Suche kann keine Daten erschaffen, die es nicht gibt. Ein winziges, verschwommenes Original kann bei keinem Ziel zu einem scharfen Bild werden.</p>\n<p>Sie kann auch die Physik nicht schlagen. Ein detailreiches Foto bei 2 KB ist unmöglich, und kein Suchalgorithmus ändert das.</p>\n<p>Sie kann ein falsches Format nicht beheben. Ein PNG-Foto bei einem engen Ziel wird verfehlen, egal wie clever die Suche ist, weil PNG nicht genug Gewicht abwerfen kann.</p>\n<p>Ändern Sie in diesen Fällen die Eingaben. Verwenden Sie ein besseres Original, wechseln Sie zu JPG oder erhöhen Sie das Ziel auf etwas Erreichbares.</p>\n<p>Die Suche ist leistungsstark, arbeitet aber innerhalb der Grenzen Ihres Bildes. Gute Eingaben hinein, gute Ergebnisse heraus.</p>\n<h2 id=\"search-history\">Woher die binäre Suche kommt</h2>\n<p>Die binäre Suche ist einer der ältesten Algorithmen der Informatik. Sie taucht in Telefonbüchern, Wörterbüchern und Ratespielen auf – überall, wo eine sortierte Liste durchsucht werden muss.</p>\n<p>Die Idee ist einfach: die Mitte prüfen, die Hälfte verwerfen und wiederholen. Es ist dieselbe Logik wie die Suche nach einem Wort in einem Wörterbuch, indem man es in der Mitte aufschlägt.</p>\n<p>Programmierer verwenden sie, um sortierte Daten jeder Größe zu durchsuchen. Eine Liste mit einer Million Einträgen braucht nur zwanzig Tests, weshalb sie überall ist.</p>\n<p>Bei der Bildkomprimierung ist die sortierte Liste der Qualitätsbereich. Die Dateigröße steigt mit der Qualität, der Bereich ist also geordnet und die binäre Suche passt perfekt.</p>\n<p>Die Geschichte zu kennen, hilft Ihnen, der Methode zu vertrauen. Es ist kein neuer Trick; es ist eine bewährte Idee, die auf ein neues Problem angewendet wird.</p>\n<h2 id=\"search-vs-ai\">Suche vs. Raten: Warum Methode Instinkt schlägt</h2>\n<p>Der menschliche Instinkt ist schlecht darin, Qualitätszahlen zu wählen. Wir bevorzugen runde Zahlen wie 70 oder 80, die selten die beste Wahl für ein bestimmtes Bild sind.</p>\n<p>Der Instinkt hört auch zu früh auf. Eine Person, die eine Qualität findet, die passt, hört meist auf, auch wenn eine etwas höhere Qualität ebenfalls passen würde.</p>\n<p>Die Suche hat keine solchen Verzerrungen. Sie testet systematisch und stoppt erst, wenn der Bereich auf einen einzigen besten Wert eingegrenzt ist.</p>\n<p>Dieser methodische Ansatz ist der ganze Vorteil. Das Tool weiß nicht mehr als Sie; es prüft einfach sorgfältiger, als Sie es tun würden.</p>\n<p>Vertrauen Sie der Methode mehr als Ihrem Bauchgefühl. Die Zahlen, die sie findet, sind jedes Mal besser als die Zahlen, die Sie raten würden.</p>\n<h2 id=\"quality-steps\">Wie fein sind die Qualitätsschritte?</h2>\n<p>Die Qualität wird meist von 1 bis 100 gemessen, was hundert mögliche Einstellungen ergibt. Die Suche testet etwa sieben davon, um die beste zu finden.</p>\n<p>Sieben Tests reichen, weil jeder Test den Bereich halbiert. Nach sieben Halbierungen ist ein Bereich von 100 auf weniger als eins geschrumpft.</p>\n<p>Feinere Schritte würden Tests hinzufügen, ohne sichtbaren Nutzen. Der Unterschied zwischen Qualität 65 und 66 ist für das Auge unsichtbar.</p>\n<p>Die Suche stoppt, wenn weitere Tests das Ergebnis nicht verbessern können. Dieser Stopppunkt ist in den Algorithmus eingebaut, nicht von Hand gewählt.</p>\n<p>Effizienz zählt hier. Weniger Tests bedeuten schnellere Ergebnisse, und schnellere Ergebnisse bedeuten ein Tool, das Menschen tatsächlich gern verwenden.</p>\n<h2 id=\"edge-cases-search\">Grenzfälle: Wenn der Bereich nicht sortiert ist</h2>\n<p>Die binäre Suche braucht einen sortierten Bereich: Höhere Qualität muss eine größere Datei bedeuten. Das ist fast immer wahr, aber nicht ganz immer.</p>\n<p>Winzige Qualitätsänderungen können gelegentlich bei höherer Qualität eine etwas kleinere Datei erzeugen, weil Encoder ihre Mathematik runden.</p>\n<p>Diese Schwankungen sind klein und die Suche toleriert sie. Sie zielt knapp unter das Ziel, eine kleine Schwankung kann das Ergebnis also nicht über die Grenze drücken.</p>\n<p>Formatwechsel brechen die Ordnung vollständig. Ein PNG mit Qualität 90 kann größer sein als ein JPG mit Qualität 50, weshalb die Suche pro Format läuft.</p>\n<p>Das Tool gleicht diese kleinen Abweichungen still aus. Sie sehen ein sauberes Ergebnis; der Algorithmus regelt das Durcheinander hinter den Kulissen.</p>\n<h2 id=\"search-and-scaling\">Wie Suche und Skalierung zusammenarbeiten</h2>\n<p>Qualitätssuche und Abmessungsskalierung sind zwei Schleifen, eine in der anderen. Die äußere Schleife versucht Abmessungen; die innere Schleife sucht bei jeder Größe nach Qualität.</p>\n<p>Das Tool beginnt in voller Größe und sucht nach Qualität. Wenn keine Qualität passt, geht es die Abmessungen nach unten und sucht erneut.</p>\n<p>Diese Verschachtelung ist effizient. Sie vermeidet es, jede Kombination aus Größe und Qualität zu testen, was weit länger dauern würde.</p>\n<p>Das Ergebnis ist das größte Bild mit der besten Qualität, das zu Ihrem Ziel passt. Keine andere Kombination schlägt es innerhalb des Suchraums.</p>\n<p>Die Verschachtelung zu verstehen, erklärt das Verhalten des Tools. Eine Datei, die herunterskaliert wurde, tat das, weil keine Qualität in voller Größe passen konnte.</p>\n<h2 id=\"future-search\">Was als Nächstes für die Zielsuche kommt</h2>\n<p>Die Suche könnte klüger werden. Künftige Versionen könnten die beste Qualität aus dem Bildinhalt vorhersagen, bevor sie überhaupt etwas testen.</p>\n<p>Eine inhaltsbewusste Suche würde näher an der Antwort beginnen und weniger Tests brauchen. Ein Porträt und eine Landschaft würden mit unterschiedlichen Qualitätsvermutungen starten.</p>\n<p>Vorläufig ist die schlichte binäre Suche schnell genug. Sieben Tests dauern Sekunden, und das Ergebnis ist bereits die beste Qualität, die passt.</p>\n<p>Das Prinzip wird sich nicht ändern. Nennen Sie das Ziel, suchen Sie systematisch und liefern Sie die schärfste Datei, die passt.</p>\n<p>Dieses Prinzip macht den Zielkompressor so einfach zu bedienen. Die Komplexität steckt im Algorithmus, und der Nutzer sieht nur ein sauberes Ergebnis.</p>\n<p>Die vollständige Anleitung zu angepassten Zielen finden Sie unter <a href=\"/de/blog/bild-auf-beliebige-dateigroesse-komprimieren-anleitung/\">Bild auf eine beliebige Dateigröße komprimieren: Die komplette Anleitung</a>. Die praktischen Schritte stehen unter <a href=\"/de/blog/bild-auf-genaue-kb-groesse-komprimieren-anleitung/\">Bild auf eine genaue KB-Größe komprimieren: Anleitung</a>. Um es selbst auszuprobieren, öffnen Sie den <a href=\"/de/bild-auf-zieldateigroesse-komprimieren/\">Zielgrößen-Kompressor</a> und tippen Sie eine beliebige Größe ein.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Wie findet das Tool die beste Qualität für meine Zielgröße?","answer":"Das Tool sucht systematisch nach der höchsten Qualitätseinstellung, die noch zu Ihrer Zielgröße passt. Es testet eine Qualitätsstufe, prüft die Ergebnisgröße, halbiert dann den übrigen Bereich und testet erneut. Nach etwa sieben Tests hat es die beste Qualität auf eine einzige Zahl eingegrenzt."},{"question":"Warum beginnt die Suche bei Qualität 50?","answer":"In der Mitte des Bereichs zu beginnen, macht die binäre Suche schnell. Jeder Test eliminiert die Hälfte der Möglichkeiten, die Suche konvergiert also in einer Handvoll Schritten. Von oben zu beginnen und herunterzuzählen, würde weit mehr Tests brauchen."},{"question":"Kann die Suche Qualität 63 finden statt einer runden Zahl wie 60 oder 70?","answer":"Ja, und das ist ihr Hauptvorteil. Die beste Qualität für Ihr Bild ist selten eine runde Zahl. Die Suche testet exakte Werte und pendelt sich auf die präzise Einstellung ein, die passt – etwa 63 oder 71 –, die ein Mensch nie raten würde."},{"question":"Funktioniert die Suche für jedes Bild gleich?","answer":"Die Methode ist dieselbe, aber das Ergebnis unterscheidet sich pro Bild. Ein einfaches Porträt pendelt sich vielleicht bei Qualität 82 ein, während eine detailreiche Landschaft bei 61 landet – selbst bei demselben Ziel. Jedes Bild bekommt seine eigene Suche und seine eigene beste Einstellung."},{"question":"Warum verringert das Tool manchmal die Abmessungen, statt nur die Qualität zu senken?","answer":"Wenn selbst die niedrigste brauchbare Qualität das Ziel in voller Größe nicht erreichen kann, sind Abmessungen der einzige Hebel, der bleibt. Das Tool geht die Pixelgröße schrittweise nach unten, führt bei jedem Schritt eine frische Qualitätssuche durch und stoppt bei der ersten Skala, die passt."},{"question":"Wird die binäre Suche auch in anderen CompressMyPic-Tools verwendet?","answer":"Ja. Die Kompressoren mit fester Größe für 50 KB, 100 KB, 200 KB und 500 KB verwenden alle dieselbe automatische Qualitätssuche mit ihrem eigenen voreingestellten Ziel. Der Zielkompressor lässt Sie einfach jede Zahl eintippen, statt eine feste zu verwenden."}];
